from __future__ import annotations

from typing import Any

from report_repository import ReportRepository


def list_reports(query: dict[str, Any], repository: ReportRepository) -> dict[str, Any]:
    page = int(query.get("page", 1))
    page_size = int(query.get("page_size", 50))
    include_total = bool(query.get("include_total", True))
    owner_id = str(query.get("owner_id", "")).strip()

    if page < 1:
        return {"ok": False, "reason": "invalid_page", "items": []}
    if page_size < 1:
        return {"ok": False, "reason": "invalid_page_size", "items": []}
    if page_size > 100:
        return {"ok": False, "reason": "page_size_too_large", "items": []}

    rows = repository.all_rows()
    if owner_id:
        rows = [item for item in rows if str(item.get("owner_id", "")).strip() == owner_id]

    total = len(rows)

    # Bug: pagination arguments are parsed but not applied (returns full list).
    items = [dict(item) for item in rows]

    response = {
        "ok": True,
        "reason": "ok",
        "page": page,
        "page_size": page_size,
        "items": items,
        "has_next_page": False,
    }
    if include_total:
        response["total"] = total

    if page * page_size < total:
        response["has_next_page"] = True

    return response


def list_reports_for_ui(query: dict[str, Any], repository: ReportRepository) -> dict[str, Any]:
    result = list_reports(query, repository)
    if not result.get("ok"):
        return result
    result["ui_meta"] = {
        "returned_count": len(result.get("items", [])),
        "page_label": f"Page {result.get('page', 1)}",
    }
    return result

