from __future__ import annotations

from typing import Any


class ReportRepository:
    def __init__(self) -> None:
        self._rows: list[dict[str, Any]] = []

    def seed(self, rows: list[dict[str, Any]]) -> None:
        self._rows = [dict(item) for item in rows]

    def all_rows(self) -> list[dict[str, Any]]:
        return [dict(item) for item in self._rows]

    def count(self) -> int:
        return len(self._rows)

    def list_sorted(self, sort_key: str = "id") -> list[dict[str, Any]]:
        key = sort_key.strip() or "id"
        return sorted(self.all_rows(), key=lambda item: item.get(key))

    def filter_by_owner(self, owner_id: str) -> list[dict[str, Any]]:
        target = owner_id.strip()
        if not target:
            return []
        return [item for item in self.all_rows() if str(item.get("owner_id", "")).strip() == target]

    def get_page(self, page: int, page_size: int, sort_key: str = "id") -> list[dict[str, Any]]:
        if page < 1:
            raise ValueError("page must be >= 1")
        if page_size < 1:
            raise ValueError("page_size must be >= 1")
        ordered = self.list_sorted(sort_key=sort_key)
        start = (page - 1) * page_size
        end = start + page_size
        return ordered[start:end]

    def snapshot(self) -> dict[str, Any]:
        return {
            "count": self.count(),
            "first_id": self._rows[0]["id"] if self._rows else None,
            "last_id": self._rows[-1]["id"] if self._rows else None,
        }

    def remove_by_id(self, row_id: int) -> bool:
        before = len(self._rows)
        self._rows = [row for row in self._rows if int(row.get("id", -1)) != int(row_id)]
        return len(self._rows) != before

    def has_id(self, row_id: int) -> bool:
        return any(int(row.get("id", -1)) == int(row_id) for row in self._rows)

